import { assumeType } from "@/lib/narrow"

type SortDirection = "asc" | "desc"

type SortSpec = { field: string; direction: SortDirection }

type PagePosition = { page: number } | { cursor: string | null; direction: "forward" | "backward" }

type PageRequest<F> = {
  filter: F
  sort: readonly SortSpec[]
  size: number
  position: PagePosition
}

type PageResult<T> = {
  items: T[]
  total?: number
  totalEstimate?: number
  hasMore?: boolean
  hasPrevious?: boolean
  nextCursor?: string | null
  prevCursor?: string | null
}

type SourceContext = { signal: AbortSignal }

type SourceCapabilities = {
  position: "page" | "cursor"
  total?: "exact" | "estimate" | "none"
  maxPageSize?: number
}

type PageSource<T, F = unknown> = {
  /** The query key prefix: every query of this source starts with it, so invalidating it refreshes them all. */
  key: readonly unknown[]
  getId(item: T): string
  capabilities: SourceCapabilities
  fetchPage(request: PageRequest<F>, context: SourceContext): Promise<PageResult<T>>
  /** A count of its own, run as a separate query that never holds back the rows. */
  fetchTotal?(filter: F, context: SourceContext): Promise<number>
}

type Navigation = "pages" | "prev-next" | "load-more" | "infinite"
type NavigationMode = Navigation | "auto"

/** What the source said about the size of the result: exact, estimated or unknown. */
type TotalInfo = { kind: "exact"; value: number } | { kind: "estimate"; value: number } | { kind: "none" }

function isPagePosition(position: PagePosition): position is { page: number } {
  return "page" in position
}

function totalOf(result: PageResult<unknown> | undefined, counted?: number): TotalInfo {
  if (result?.total !== undefined && Number.isFinite(result.total)) return { kind: "exact", value: result.total }
  if (counted !== undefined && Number.isFinite(counted)) return { kind: "exact", value: counted }
  if (result?.totalEstimate !== undefined && Number.isFinite(result.totalEstimate))
    return { kind: "estimate", value: result.totalEstimate }
  return { kind: "none" }
}

/**
 * `"auto"` follows what the source gives: page numbers with an exact total, previous and next with an estimate or
 * only `hasMore`, and load more for a cursor. Before the first result it goes by the declared capabilities.
 */
function resolveNavigation(
  capabilities: SourceCapabilities,
  mode: NavigationMode = "auto",
  total: TotalInfo = { kind: "none" },
): Navigation {
  if (mode !== "auto") return mode
  if (capabilities.position === "cursor") return "load-more"
  if (total.kind === "exact") return "pages"
  if (total.kind === "none" && capabilities.total === "exact") return "pages"
  return "prev-next"
}

function pageCountOf(total: number, size: number) {
  return size > 0 ? Math.max(1, Math.ceil(total / size)) : 1
}

/** Caps a page size at the source's `maxPageSize` and keeps it a positive integer. */
function capPageSize(size: number, capabilities: SourceCapabilities) {
  const whole = Number.isFinite(size) ? Math.max(1, Math.trunc(size)) : 1
  return capabilities.maxPageSize === undefined ? whole : Math.min(whole, capabilities.maxPageSize)
}

function capPageSizes(sizes: readonly number[], capabilities: SourceCapabilities) {
  return [...new Set(sizes.map((size) => capPageSize(size, capabilities)))].toSorted((a, b) => a - b)
}

type PageRange = { from: number; to: number; total: TotalInfo }

type PageStatusLabels = {
  /**
   * "Showing 21–40 of 312", "Showing 21–40 of about 300" or "Showing 21–40", with the numbers in `locale` (the
   * page's language in the components, from `useLocale`).
   */
  range: (range: PageRange, locale?: string) => string
  empty: string
  loading: string
}

const numberFormats = new Map<string, Intl.NumberFormat>()

/** A number in `locale` (the runtime's default when undefined), with one cached `Intl.NumberFormat` per locale. */
function formatCount(value: number, locale?: string) {
  const key = locale ?? ""
  let format = numberFormats.get(key)
  if (!format) {
    format = new Intl.NumberFormat(locale)
    numberFormats.set(key, format)
  }
  return format.format(value)
}

const pageStatusLabels: PageStatusLabels = {
  range: ({ from, to, total }, locale) => {
    const shown = `Showing ${formatCount(from, locale)}–${formatCount(to, locale)}`
    if (total.kind === "exact") return `${shown} of ${formatCount(total.value, locale)}`
    if (total.kind === "estimate") return `${shown} of about ${formatCount(total.value, locale)}`
    return shown
  },
  empty: "No results",
  loading: "Loading…",
}

/** The first and last row shown, 1-based, for the live region. `offset` is how many rows come before the page. */
function pageRange(offset: number, count: number, total: TotalInfo): PageRange | undefined {
  if (count === 0) return undefined
  return { from: offset + 1, to: offset + count, total }
}

type ParamValue = string | number | boolean | null | undefined
type ParamsInit =
  | URLSearchParams
  | Iterable<readonly [string, string]>
  | Readonly<Record<string, ParamValue | readonly ParamValue[]>>

function appendParams(target: URLSearchParams, init: ParamsInit | undefined) {
  if (init === undefined) return target
  const entries: Iterable<readonly [string, unknown]> =
    init instanceof URLSearchParams || Symbol.iterator in init
      ? (init as Iterable<readonly [string, string]>)
      : Object.entries(init)
  for (const [name, value] of entries) {
    for (const item of Array.isArray(value) ? (value as unknown[]) : [value]) {
      if (item === undefined || item === null) continue
      target.append(name, String(item))
    }
  }
  return target
}

type SortStyle = "comma" | "dot" | "sign" | ((sort: readonly SortSpec[], params: URLSearchParams) => void)

/**
 * How sort goes on the wire: `"comma"` repeats `sort=name,asc` (Spring), `"dot"` writes `sort=name.asc,id.desc`,
 * `"sign"` writes `sort=name,-id` (JSON:API).
 */
function writeSort(params: URLSearchParams, sort: readonly SortSpec[], style: SortStyle = "comma", name = "sort") {
  if (typeof style === "function") return style(sort, params)
  if (sort.length === 0) return
  if (style === "comma") for (const spec of sort) params.append(name, `${spec.field},${spec.direction}`)
  else if (style === "dot") params.set(name, sort.map((spec) => `${spec.field}.${spec.direction}`).join(","))
  else params.set(name, sort.map((spec) => (spec.direction === "desc" ? `-${spec.field}` : spec.field)).join(","))
}

type CursorPosition = Exclude<PagePosition, { page: number }>

/** What an adapter hands your `request`: the query to send, and the request it came from. */
type RestCall<F> = {
  params: URLSearchParams
  /** `params` as a query string, without the `?`. */
  query: string
  request: PageRequest<F>
  signal: AbortSignal
}

type RestSourceOptions<T, F, Raw> = {
  key: readonly unknown[]
  getId: (item: T) => string
  /** Sends the call: `fetch(\`/api/tasks?${call.query}\`, { signal: call.signal }).then(readJson)`. */
  request: (call: RestCall<F>) => Promise<Raw>
  /** The filter as query params, usually a serializer's output. */
  params?: (filter: F) => ParamsInit
  sortStyle?: SortStyle
  sortParam?: string
  maxPageSize?: number
  /** Whether responses carry an exact total. Default `"exact"`. */
  total?: SourceCapabilities["total"]
  fetchTotal?: (filter: F, context: SourceContext) => Promise<number>
}

type AdapterIdentity<T, F> = {
  key: readonly unknown[]
  getId: (item: T) => string
  fetchTotal?: (filter: F, context: SourceContext) => Promise<number>
}

function adapterSource<T, F>(
  identity: AdapterIdentity<T, F>,
  capabilities: SourceCapabilities,
  fetchPage: PageSource<T, F>["fetchPage"],
): PageSource<T, F> {
  return {
    key: identity.key,
    getId: identity.getId,
    capabilities,
    fetchPage,
    ...(identity.fetchTotal ? { fetchTotal: identity.fetchTotal } : {}),
  }
}

function restCallOf<F>(request: PageRequest<F>, context: SourceContext, params: URLSearchParams): RestCall<F> {
  return { params, query: params.toString(), request, signal: context.signal }
}

/** The 1-based page a request asks for; throws when it carries a cursor. */
function pageNumberOf<F>(request: PageRequest<F>) {
  if (!isPagePosition(request.position)) throw new TypeError("This source pages by number; it got a cursor.")
  return Math.max(1, Math.trunc(request.position.page))
}

/** The cursor a request asks for; throws when it carries a page number. */
function cursorPositionOf<F>(request: PageRequest<F>): CursorPosition {
  if (isPagePosition(request.position)) throw new TypeError("This source pages by cursor; it got a page number.")
  return request.position
}

/** A failed HTTP response. `status` is what DataProvider's retry reads: a 4xx is never retried. */
class HttpError extends Error {
  readonly status: number
  readonly response: Response | undefined

  constructor(status: number, message?: string, response?: Response) {
    super(message ?? `Request failed with status ${String(status)}`)
    this.name = "HttpError"
    this.status = status
    this.response = response
  }
}

/** Reads a response's JSON body, or throws an `HttpError` with its status. */
async function readJson<Raw>(response: Response): Promise<Raw> {
  if (!response.ok) throw new HttpError(response.status, response.statusText || undefined, response)
  const body: unknown = await response.json()
  // Workaround: the caller names the body's shape; a JSON body can't be checked against a type it only knows by name.
  return assumeType<Raw>(body)
}

function abortError(signal: AbortSignal): unknown {
  return signal.reason ?? new DOMException("The operation was aborted.", "AbortError")
}

function isAbortError(error: unknown) {
  return error instanceof DOMException && error.name === "AbortError"
}

export {
  abortError,
  adapterSource,
  appendParams,
  capPageSize,
  capPageSizes,
  cursorPositionOf,
  formatCount,
  HttpError,
  isAbortError,
  isPagePosition,
  pageCountOf,
  pageNumberOf,
  pageRange,
  pageStatusLabels,
  readJson,
  resolveNavigation,
  restCallOf,
  totalOf,
  writeSort,
}
export type {
  AdapterIdentity,
  CursorPosition,
  Navigation,
  NavigationMode,
  PagePosition,
  PageRange,
  PageRequest,
  PageResult,
  PageSource,
  PageStatusLabels,
  ParamsInit,
  ParamValue,
  RestCall,
  RestSourceOptions,
  SortDirection,
  SortSpec,
  SortStyle,
  SourceCapabilities,
  SourceContext,
  TotalInfo,
}

import {
  abortError,
  isPagePosition,
  type PageRequest,
  type PageResult,
  type PageSource,
  type SortSpec,
  type SourceCapabilities,
} from "@/lib/page-source"
import { isRecord } from "@/lib/narrow"

type ArraySortValue = string | number | bigint | boolean | Date | null | undefined

type ArraySourceOptions<T, F> = {
  /** Default `["array-source", n]`, one per source. Pass your own to invalidate it by name. */
  key?: readonly unknown[]
  /** Default: the item's `id`, as a string. */
  getId?: (item: T) => string
  /** Keeps an item for the request's filter. */
  filter?: (item: T, filter: F) => boolean
  /** Free-text search: `fields` read from each item, matched case-insensitively against `filter[param]` (`"q"`). */
  search?: { fields: readonly (keyof T & string)[]; param?: string } | ((item: T, filter: F) => boolean)
  /** Sort values by field; any other field sorts by the item's property of that name. */
  sort?: Readonly<Record<string, (item: T) => ArraySortValue>>
  /** `"page"` (default) or `"cursor"`, to try cursor paging. */
  position?: SourceCapabilities["position"]
  /** What totals to report: `"exact"` (default), `"estimate"` (rounded up to tens) or `"none"` (only `hasMore`). */
  total?: "exact" | "estimate" | "none"
  maxPageSize?: number
  /** Simulated latency in ms. Default 0. */
  delay?: number | ((request: PageRequest<F>) => number)
  /** Return an error to fail that request: `(request, call) => call % 3 === 2 ? new Error("Flaky") : undefined`. */
  fail?: (request: PageRequest<F>, call: number) => unknown
  /** Adds a separate `fetchTotal`, with its own latency. */
  count?: { delay?: number }
}

let sources = 0

const collator = new Intl.Collator(undefined, { numeric: true, sensitivity: "base" })

function compareValues(a: ArraySortValue, b: ArraySortValue) {
  const missingA = a === null || a === undefined
  const missingB = b === null || b === undefined
  if (missingA || missingB) return missingA === missingB ? 0 : missingA ? 1 : -1
  if (typeof a === "string" && typeof b === "string") return collator.compare(a, b)
  const left = a instanceof Date ? a.getTime() : a
  const right = b instanceof Date ? b.getTime() : b
  if (left === right) return 0
  return lessThan(left, right) ? -1 : 1
}

// Workaround: `<` on mixed primitives compares them as numbers, which TypeScript only allows on numbers, bigints or two strings.
function lessThan(left: string | number | bigint | boolean, right: string | number | bigint | boolean) {
  if (typeof left === "bigint" && typeof right === "bigint") return left < right
  return Number(left) < Number(right)
}

function asSortValue(value: unknown): ArraySortValue {
  if (value === null || value === undefined || value instanceof Date) return value
  if (typeof value === "string" || typeof value === "number" || typeof value === "bigint" || typeof value === "boolean")
    return value
  return String(value)
}

function defaultId(item: unknown) {
  if (typeof item === "object" && item !== null && "id" in item) return String((item as { id: unknown }).id)
  return String(item)
}

function wait(ms: number, signal: AbortSignal) {
  return new Promise<void>((resolve, reject) => {
    if (signal.aborted) return reject(abortError(signal))
    if (ms <= 0) return resolve()
    const onAbort = () => {
      clearTimeout(timer)
      reject(abortError(signal))
    }
    const timer = setTimeout(() => {
      signal.removeEventListener("abort", onAbort)
      resolve()
    }, ms)
    signal.addEventListener("abort", onAbort, { once: true })
  })
}

/** An in-memory `PageSource` for demos, tests and mockups: filters, searches, sorts and pages an array. */
function arraySource<T, F = Record<string, unknown>>(
  items: readonly T[],
  options: ArraySourceOptions<T, F> = {},
): PageSource<T, F> {
  const { getId = defaultId, position = "page", total = "exact" } = options
  const key = options.key ?? ["array-source", ++sources]
  let calls = 0

  const sortValue = (field: string) =>
    options.sort?.[field] ?? ((item: T) => asSortValue(isRecord(item) ? item[field] : undefined))

  const matches = (item: T, filter: F) => {
    if (options.filter && !options.filter(item, filter)) return false
    const search = options.search
    if (search === undefined) return true
    if (typeof search === "function") return search(item, filter)
    const text = isRecord(filter) ? filter[search.param ?? "q"] : undefined
    if (typeof text !== "string" || text.trim() === "") return true
    const needle = text.trim().toLocaleLowerCase()
    return search.fields.some((field) =>
      String(item[field] ?? "")
        .toLocaleLowerCase()
        .includes(needle),
    )
  }

  const select = (filter: F, sort: readonly SortSpec[]) => {
    const kept = items.filter((item) => matches(item, filter))
    if (sort.length === 0) return kept
    const readers = sort.map((spec) => ({ read: sortValue(spec.field), sign: spec.direction === "desc" ? -1 : 1 }))
    return kept
      .map((item, index) => ({ item, index }))
      .toSorted((a, b) => {
        for (const { read, sign } of readers) {
          const left = read(a.item)
          const right = read(b.item)
          const missing = left === null || left === undefined || right === null || right === undefined
          const order = missing ? compareValues(left, right) : sign * compareValues(left, right)
          if (order !== 0) return order
        }
        return a.index - b.index
      })
      .map((entry) => entry.item)
  }

  const settle = async (request: PageRequest<F>, signal: AbortSignal) => {
    const call = calls++
    const ms = typeof options.delay === "function" ? options.delay(request) : (options.delay ?? 0)
    await wait(ms, signal)
    const error = options.fail?.(request, call)
    if (error !== undefined && error !== null) throw error
  }

  const source: PageSource<T, F> = {
    key,
    getId,
    capabilities: { position, total, maxPageSize: options.maxPageSize },
    async fetchPage(request, { signal }) {
      await settle(request, signal)
      const rows = select(request.filter, request.sort)
      const size = Math.max(1, request.size)
      let start: number
      if (isPagePosition(request.position)) start = (Math.max(1, request.position.page) - 1) * size
      else {
        const at = request.position.cursor === null ? Number.NaN : Number(request.position.cursor)
        if (request.position.direction === "forward") start = Number.isInteger(at) ? at : 0
        else start = Number.isInteger(at) ? Math.max(0, at - size) : Math.max(0, rows.length - size)
      }
      const end = Math.min(rows.length, start + size)
      const result: PageResult<T> = {
        items: rows.slice(start, end),
        hasMore: end < rows.length,
        hasPrevious: start > 0,
      }
      if (!isPagePosition(request.position)) {
        result.nextCursor = end < rows.length ? String(end) : null
        result.prevCursor = start > 0 ? String(start) : null
      }
      if (total === "exact" && options.count === undefined) result.total = rows.length
      if (total === "estimate") result.totalEstimate = Math.ceil(rows.length / 10) * 10
      return result
    },
  }
  if (options.count) {
    const countDelay = options.count.delay ?? 0
    source.fetchTotal = async (filter, { signal }) => {
      await wait(countDelay, signal)
      return select(filter, []).length
    }
  }
  return source
}

export { arraySource }
export type { ArraySortValue, ArraySourceOptions }

import { assumeType } from "@/lib/narrow"
import {
  capPageSize,
  capPageSizes,
  pageRange,
  pageStatusLabels,
  resolveNavigation,
  totalOf,
  type Navigation,
  type NavigationMode,
  type PageRequest,
  type PageResult,
  type PageSource,
  type PageStatusLabels,
  type SortSpec,
} from "@/lib/page-source"

/** The shape of `url-state`'s adapters; any object with these three methods works. */
type UrlAdapterLike = {
  read(): URLSearchParams
  write(params: URLSearchParams, options: { replace: boolean }): void
  subscribe(callback: () => void): () => void
}

type UrlStateLike<F> = { filter: F; sort: readonly SortSpec[]; page: number; size: number; cursor?: string | null }

/** The shape of `filter-schema`'s `createUrlCodec`. */
type PageCodecLike<F> = {
  decode(params: URLSearchParams): UrlStateLike<F>
  merge(current: URLSearchParams, state: UrlStateLike<F>): URLSearchParams
  owns(name: string): boolean
}

type UrlHistory = "replace" | "push" | "push-page"

type PageControllerOptions<F> = {
  filter?: F
  sort?: readonly SortSpec[]
  /** `"multi"` lets `toggleSort(field, { additive: true })` (Shift+click) add a field. Default `"single"`. */
  sortMode?: "single" | "multi"
  pageSize?: number
  pageSizes?: readonly number[]
  navigation?: NavigationMode
  /** The filter key a search box edits; `setSearch` commits to it after `debounce` ms (250). */
  search?: { key: keyof F & string; debounce?: number }
  /** Keeps the state in the URL. `history: "replace"` (default), `"push"`, or `"push-page"` (push on paging only). */
  url?: { adapter: UrlAdapterLike; codec: PageCodecLike<F>; history?: UrlHistory }
  labels?: Partial<PageStatusLabels>
}

type PageControllerState<F> = {
  filter: F
  sort: readonly SortSpec[]
  size: number
  page: number
  cursor: string | null
  direction: "forward" | "backward"
  /** How many cursor pages lie before this one, for "Showing 41–60". */
  cursorIndex: number
  /** The search box's text, ahead of the debounced filter. */
  searchText: string
  request: PageRequest<F>
}

type PageController<F> = {
  getState(): PageControllerState<F>
  subscribe(listener: () => void): () => void
  readonly pageSizes: readonly number[]
  setFilter(next: F | ((previous: F) => F)): void
  setFilterValue<Key extends keyof F>(key: Key, value: F[Key] | undefined): void
  resetFilters(): void
  setSearch(text: string, options?: { immediate?: boolean }): void
  flushSearch(): void
  setSort(sort: readonly SortSpec[]): void
  toggleSort(field: string, options?: { additive?: boolean; direction?: SortSpec["direction"] }): void
  setPageSize(size: number): void
  setPage(page: number): void
  /** The next page; a cursor source needs the current result for its `nextCursor`. */
  next(result?: PageResult<unknown>): void
  previous(result?: PageResult<unknown>): void
  navigation(result?: PageResult<unknown>, counted?: number): Navigation
  /** "Showing 21–40 of 312" for the live region, numbers in `locale`; `undefined` before the first result. */
  statusText(result: PageResult<unknown> | undefined, counted?: number, locale?: string): string | undefined
  /** Starts following the URL. Returns the cleanup; call it from an effect. */
  connect(): () => void
  /** Drops a pending search commit. */
  dispose(): void
}

function same(a: unknown, b: unknown) {
  return a === b || JSON.stringify(a) === JSON.stringify(b)
}

function requestOf<F>(state: Omit<PageControllerState<F>, "request">, cursorMode: boolean): PageRequest<F> {
  return {
    filter: state.filter,
    sort: state.sort,
    size: state.size,
    position: cursorMode ? { cursor: state.cursor, direction: state.direction } : { page: state.page },
  }
}

const isUpdater = <F>(next: F | ((previous: F) => F)): next is (previous: F) => F => typeof next === "function"

/**
 * The state of one paged view, outside React: filter, sort, size and position, as a `PageRequest`. A new filter,
 * sort or size goes back to the first page; search is debounced; the URL follows when `url` is set.
 */
function createPageController<T, F>(
  source: PageSource<T, F>,
  options: PageControllerOptions<F> = {},
): PageController<F> {
  const { capabilities } = source
  const cursorMode = capabilities.position === "cursor"
  const labels = { ...pageStatusLabels, ...options.labels }
  const pageSizes = capPageSizes(options.pageSizes ?? [10, 25, 50, 100], capabilities)
  // Workaround: a controller without `filter` starts unfiltered; filters are records of optional fields, which `F` doesn't state.
  const initialFilter = options.filter ?? assumeType<F>({})
  const searchKey = options.search?.key
  const debounce = options.search?.debounce ?? 250
  const listeners = new Set<() => void>()
  let timer: ReturnType<typeof setTimeout> | undefined

  const searchTextOf = (filter: F) => {
    const value = searchKey === undefined ? undefined : filter[searchKey]
    return typeof value === "string" ? value : ""
  }

  const fromUrl = () => {
    const url = options.url
    if (!url) return undefined
    const params = url.adapter.read()
    if (![...params.keys()].some((key) => url.codec.owns(key))) return undefined
    return url.codec.decode(params)
  }

  const build = (next: Omit<PageControllerState<F>, "request">): PageControllerState<F> => ({
    ...next,
    request: requestOf(next, cursorMode),
  })

  const initialUrl = fromUrl()
  let state = build({
    filter: initialUrl?.filter ?? initialFilter,
    sort: initialUrl?.sort ?? options.sort ?? [],
    size: capPageSize(initialUrl?.size ?? options.pageSize ?? 25, capabilities),
    page: initialUrl?.page ?? 1,
    cursor: initialUrl?.cursor ?? null,
    direction: "forward",
    cursorIndex: 0,
    searchText: searchTextOf(initialUrl?.filter ?? initialFilter),
  })

  const writeUrl = (previous: PageControllerState<F>) => {
    const url = options.url
    if (!url) return
    const current = url.adapter.read()
    const next = url.codec.merge(current, state)
    if (next.toString() === current.toString()) return
    const history = url.history ?? "replace"
    const paged =
      (previous.page !== state.page || previous.cursor !== state.cursor) &&
      same([previous.filter, previous.sort, previous.size], [state.filter, state.sort, state.size])
    url.adapter.write(next, { replace: history === "replace" || (history === "push-page" && !paged) })
  }

  const set = (patch: Partial<Omit<PageControllerState<F>, "request">>, { url = true } = {}) => {
    const previous = state
    const next = build({ ...state, ...patch })
    if (same(requestOf(next, cursorMode), previous.request) && next.searchText === previous.searchText) return
    state = next
    if (url) writeUrl(previous)
    for (const listener of listeners) listener()
  }

  const firstPage = { page: 1, cursor: null, direction: "forward" as const, cursorIndex: 0 }

  const setFilter = (next: F | ((previous: F) => F)) => {
    const filter = isUpdater(next) ? next(state.filter) : next
    if (same(filter, state.filter)) return
    clearTimeout(timer)
    set({ filter, searchText: searchTextOf(filter), ...firstPage })
  }

  const commitSearch = (text: string) => {
    if (searchKey === undefined) return
    const value = text.trim() === "" ? undefined : text
    if (same(state.filter[searchKey], value)) return
    const filter = { ...state.filter }
    if (value === undefined) delete filter[searchKey]
    // Workaround: `search.key` names the filter's text field; TypeScript can't tie a key from options to a string value.
    else filter[searchKey] = assumeType<F[typeof searchKey]>(value)
    set({ filter, ...firstPage })
  }

  const controller: PageController<F> = {
    getState: () => state,
    subscribe(listener) {
      listeners.add(listener)
      return () => {
        listeners.delete(listener)
      }
    },
    pageSizes,
    setFilter,
    setFilterValue(key, value) {
      setFilter((previous) => {
        const next = { ...previous }
        if (value === undefined) delete next[key]
        else next[key] = value
        return next
      })
    },
    resetFilters: () => setFilter(initialFilter),
    setSearch(text, { immediate = false } = {}) {
      if (searchKey === undefined) throw new TypeError("setSearch needs the `search` option.")
      clearTimeout(timer)
      set({ searchText: text }, { url: false })
      if (immediate || debounce <= 0) commitSearch(text)
      else timer = setTimeout(() => commitSearch(text), debounce)
    },
    flushSearch() {
      clearTimeout(timer)
      commitSearch(state.searchText)
    },
    setSort(sort) {
      if (same(sort, state.sort)) return
      set({ sort: [...sort], ...firstPage })
    },
    toggleSort(field, { additive = false, direction } = {}) {
      const current = state.sort.find((spec) => spec.field === field)
      const flipped = direction ?? (current?.direction === "asc" ? "desc" : "asc")
      if (options.sortMode === "multi" && additive) {
        const sort = current
          ? state.sort.map((spec) => (spec.field === field ? { field, direction: flipped } : spec))
          : [...state.sort, { field, direction: direction ?? "asc" }]
        return controller.setSort(sort)
      }
      const only = state.sort.length === 1 && current
      controller.setSort([{ field, direction: direction ?? (only ? flipped : "asc") }])
    },
    setPageSize(size) {
      const capped = capPageSize(size, capabilities)
      if (capped === state.size) return
      set({ size: capped, ...firstPage })
    },
    setPage(page) {
      const whole = Math.max(1, Math.trunc(page))
      if (!cursorMode) set({ page: whole })
      else if (whole === 1) set(firstPage)
    },
    next(result) {
      if (!cursorMode) return set({ page: state.page + 1 })
      const cursor = result?.nextCursor ?? null
      if (cursor === null) return
      set({ cursor, direction: "forward", cursorIndex: state.cursorIndex + 1 })
    },
    previous(result) {
      if (!cursorMode) return set({ page: Math.max(1, state.page - 1) })
      const cursor = result?.prevCursor ?? null
      if (state.cursorIndex <= 1 || cursor === null) return set(firstPage)
      set({ cursor, direction: "backward", cursorIndex: state.cursorIndex - 1 })
    },
    navigation: (result, counted) => resolveNavigation(capabilities, options.navigation, totalOf(result, counted)),
    statusText(result, counted, locale) {
      if (!result) return undefined
      if (result.items.length === 0) return labels.empty
      const offset = cursorMode ? state.cursorIndex * state.size : (state.page - 1) * state.size
      const range = pageRange(offset, result.items.length, totalOf(result, counted))
      return range ? labels.range(range, locale) : labels.empty
    },
    connect() {
      const url = options.url
      if (!url) return () => {}
      const apply = () => {
        const decoded = fromUrl() ?? { filter: initialFilter, sort: options.sort ?? [], page: 1, size: state.size }
        clearTimeout(timer)
        set(
          {
            filter: decoded.filter,
            sort: decoded.sort,
            size: capPageSize(decoded.size, capabilities),
            page: decoded.page,
            cursor: decoded.cursor ?? null,
            searchText: searchTextOf(decoded.filter),
          },
          { url: false },
        )
      }
      apply()
      return url.adapter.subscribe(apply)
    },
    dispose() {
      clearTimeout(timer)
    },
  }
  return controller
}

